/// <summary>
/// N.Freidenberger 16.09.2025
/// </summary>
/// <param name = "_dataContract">_dataContract</param>
public void runService(AVABPJobsCalculationBatchTaskContract        _dataContract)
{
    if (conPeek(_dataContract.parmProcessingInterval(),2) != conpeek(_dataContract.parmProcessingInterval(),3))
    {
        info(strFmt("@NDX:NXAProcessingOfBP",conPeek(_dataContract.parmProcessingInterval(),1),conPeek(_dataContract.parmProcessingInterval(),2)));
    }
    else
    {
        Info(strFmt("@NDX:NXAProcessingOfBPFrom",conPeek(_dataContract.parmProcessingInterval(),1)));
    }
    AVABPJobsController     avaBPJobsController = AVABPJobsController::newFromBatchTask(_dataContract);
    AVABPJobsController.runOperation();
}
